      if (node[key] !== null && typeof node[key] === "object" && !Array.isArray(node[key])) {
        walk(node[key], path);
      } else {
        flat[path] = node[key];
      }
    }
  }
  walk(obj, "");
  return flat;
}

function main() {
  const input = require('fs').readFileSync(0, 'utf-8').trim();
  if (!input) return;
  console.log(JSON.stringify(solve(JSON.parse(input))));
}

if (require.main === module) main();

